  50% {
    transform: translateY(calc(155px * var(--sw-scale)));
  }

  100% {
    transform: translateY(calc(35px * var(--sw-scale)));
  }
}

@keyframes scan-bounce {
  0% {
    transform: translateY(calc(35px * var(--sw-scale)));
